import{_ as t,o as r,c as i,a5 as a}from"./chunks/framework.UjrY2eRK.js";const m=JSON.parse('{"title":"Issue 21 Drizzle integration research","description":"","frontmatter":{},"headers":[],"relativePath":"research/issue-21-drizzle-integration.md","filePath":"research/issue-21-drizzle-integration.md","lastUpdated":1788169631000}'),o={name:"research/issue-21-drizzle-integration.md"};function n(s,e,d,l,c,h){return r(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="issue-21-drizzle-integration-research" tabindex="-1">Issue 21 Drizzle integration research <a class="header-anchor" href="#issue-21-drizzle-integration-research" aria-label="Permalink to &quot;Issue 21 Drizzle integration research&quot;">​</a></h1><p>Research date: 2026-08-31</p><p>Issue: <a href="https://github.com/quwisky/trinity-push-gateway/issues/21" target="_blank" rel="noreferrer">#21, Adopt Drizzle for the D1 and Bun storage adapters</a></p><h2 id="scope-and-version-boundary" tabindex="-1">Scope and version boundary <a class="header-anchor" href="#scope-and-version-boundary" aria-label="Permalink to &quot;Scope and version boundary&quot;">​</a></h2><p>This note checks the issue against the published source for exactly:</p><ul><li><a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/package.json#L1-L4" target="_blank" rel="noreferrer"><code>drizzle-orm</code> 0.45.2</a>, tag commit <a href="https://github.com/drizzle-team/drizzle-orm/commit/273c78071d4841b497f5144734b38294df7ec64b" target="_blank" rel="noreferrer"><code>273c780</code></a>.</li><li><a href="https://github.com/drizzle-team/drizzle-orm/blob/drizzle-kit%400.31.10/drizzle-kit/package.json#L1-L4" target="_blank" rel="noreferrer"><code>drizzle-kit</code> 0.31.10</a>, tag commit <a href="https://github.com/drizzle-team/drizzle-orm/commit/4aa6ecfee4b4728dadf6f77f071a149878a3c6c0" target="_blank" rel="noreferrer"><code>4aa6ecf</code></a>.</li></ul><p>Current unversioned documentation is used only where it describes the owning platform&#39;s contract (Cloudflare D1, Bun, and SQLite). Version-sensitive Drizzle claims below point to the tagged source.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The issue is feasible without merging the two storage adapters:</p><ol><li>Define one shared <code>drizzle-orm/sqlite-core</code> schema for the two application tables.</li><li>Wrap the existing D1 binding with <code>drizzle-orm/d1</code> and the already-configured <code>bun:sqlite</code> <code>Database</code> with <code>drizzle-orm/bun-sqlite</code>.</li><li>Move ordinary selects, conditional upserts, updates, and deletes to the shared SQLite query-builder vocabulary.</li><li>Keep D1 atomic groups as D1 batches and keep Bun&#39;s exact immediate-transaction and operational SQL boundaries native/raw, as required by <a href="./../architecture/adr/0023-use-drizzle-within-runtime-specific-storage-adapters.html">ADR 0023</a> and issue #21.</li><li>Use Drizzle Kit only to generate and validate reviewed artifacts. Keep Wrangler and the existing Bun compatibility runner as the migration executors.</li></ol><p>Two limitations need explicit handling: Drizzle cannot model <code>WITHOUT ROWID</code>, and Drizzle Kit 0.31.10 does not produce byte-identical metadata in a clean-room regeneration.</p><h2 id="runtime-drivers" tabindex="-1">Runtime drivers <a class="header-anchor" href="#runtime-drivers" aria-label="Permalink to &quot;Runtime drivers&quot;">​</a></h2><h3 id="d1" tabindex="-1">D1 <a class="header-anchor" href="#d1" aria-label="Permalink to &quot;D1&quot;">​</a></h3><p><code>drizzle-orm/d1</code> accepts an existing <code>D1Database</code>, an optional Drizzle configuration including <code>schema</code>, and returns a typed SQLite database with the original binding exposed as <code>$client</code>. The database uses the asynchronous SQLite dialect. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/d1/driver.ts#L24-L77" target="_blank" rel="noreferrer">Tagged driver source</a></p><p>The D1 driver exposes a typed <code>db.batch([...])</code>. It accepts a non-empty tuple of unexecuted Drizzle SQLite query objects, prepares and binds each one, calls the native D1 <code>client.batch(...)</code> once, and maps each native <code>D1Result</code> back to the query&#39;s Drizzle result shape in tuple order. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/d1/driver.ts#L32-L36" target="_blank" rel="noreferrer">Database batch signature</a> and <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/d1/session.ts#L77-L108" target="_blank" rel="noreferrer">session implementation</a></p><p>Consequences:</p><ul><li>A select or DML statement with <code>returning()</code> is mapped to rows, not left as a raw <code>D1Result</code>.</li><li>Code that needs native metadata or a batch item which remains intentionally raw can use <code>$client</code> and the native prepared statement API.</li><li>Cloudflare documents <code>D1Database.batch()</code> as an ordered SQL transaction which aborts or rolls back the whole sequence on failure, so it remains the required atomic D1 boundary. <a href="https://developers.cloudflare.com/d1/worker-api/d1-database/#batch" target="_blank" rel="noreferrer">Cloudflare D1 batch contract</a></li></ul><p>Drizzle ORM 0.45.2 also exposes <code>db.transaction()</code> for D1, but its implementation sends <code>BEGIN</code>, the callback&#39;s statements, and <code>COMMIT</code> or <code>ROLLBACK</code> as separate session calls; nested transactions similarly send savepoint statements. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/d1/session.ts#L111-L145" target="_blank" rel="noreferrer">Tagged D1 transaction implementation</a> Cloudflare documents D1 as auto-commit and identifies <code>batch()</code> as the transactional multi-statement API. Therefore the Drizzle transaction callback is not a substitute for the issue&#39;s explicit D1 batch boundaries. <a href="https://developers.cloudflare.com/d1/worker-api/d1-database/#batch" target="_blank" rel="noreferrer">Cloudflare D1 database contract</a></p><p>The missing-row sentinel changes at the Drizzle boundary. Native <code>D1PreparedStatement.first()</code> returns <code>null</code> for no row, while the Drizzle D1 prepared query&#39;s <code>get()</code> returns <code>undefined</code>. <a href="https://developers.cloudflare.com/d1/worker-api/prepared-statements/#first" target="_blank" rel="noreferrer">Native D1 <code>first()</code></a> and <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/d1/session.ts#L238-L258" target="_blank" rel="noreferrer">tagged Drizzle <code>get()</code></a></p><h3 id="bun-sqlite" tabindex="-1">Bun SQLite <a class="header-anchor" href="#bun-sqlite" aria-label="Permalink to &quot;Bun SQLite&quot;">​</a></h3><p><code>drizzle-orm/bun-sqlite</code> can accept an existing <code>Database</code> as <code>drizzle({ client, schema })</code> and exposes it as <code>$client</code>. Its convenience connection options include <code>readonly</code>, <code>create</code>, and <code>readwrite</code>, but not Bun&#39;s <code>strict</code> option. The existing adapter should therefore continue constructing and configuring the native <code>Database</code> itself, then wrap that instance; otherwise its current strict mode would be lost. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/bun-sqlite/driver.ts#L23-L55" target="_blank" rel="noreferrer">Tagged Bun driver construction and option types</a> and <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/bun-sqlite/driver.ts#L85-L142" target="_blank" rel="noreferrer">client overload</a></p><p>The Bun driver is synchronous. It implements <code>run</code>, <code>all</code>, <code>get</code>, and <code>values</code>; <code>get()</code> returns <code>undefined</code> when no row exists. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/bun-sqlite/session.ts#L103-L168" target="_blank" rel="noreferrer">Tagged Bun prepared-query implementation</a> The database-level mutation run result is typed as <code>void</code>, so use <code>returning()</code> or the native client rather than depending on mutation metadata through the generic Drizzle <code>run()</code> type. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/bun-sqlite/driver.ts#L17-L21" target="_blank" rel="noreferrer">Tagged Bun database result kind</a></p><p>Drizzle&#39;s Bun transaction wrapper is synchronous and forwards <code>deferred</code>, <code>immediate</code>, or <code>exclusive</code> behavior to the corresponding native Bun transaction wrapper; nested transactions use savepoints. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/bun-sqlite/session.ts#L68-L100" target="_blank" rel="noreferrer">Tagged Drizzle Bun transaction implementation</a> Bun itself documents that <code>.immediate()</code> uses <code>BEGIN IMMEDIATE</code>. <a href="https://bun.sh/docs/runtime/sqlite#transactions" target="_blank" rel="noreferrer">Bun transaction contract</a> This proves the capability exists, but issue #21 expressly reserves <code>BEGIN IMMEDIATE</code> and compatibility/startup behavior as narrow raw boundaries, so adoption need not move those boundaries into Drizzle.</p><h3 id="shared-raw-escape-hatch" tabindex="-1">Shared raw escape hatch <a class="header-anchor" href="#shared-raw-escape-hatch" aria-label="Permalink to &quot;Shared raw escape hatch&quot;">​</a></h3><p>The base SQLite database also accepts an SQL wrapper or string through <code>run</code>, <code>all</code>, <code>get</code>, and <code>values</code>. Strings become <code>sql.raw(...)</code>. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/sqlite-core/db.ts#L533-L586" target="_blank" rel="noreferrer">Tagged base SQLite raw methods</a> For this repository, <code>$client</code> is the clearer escape hatch when the native runtime API itself is part of the contract: D1 batches, Bun transaction mode, connection PRAGMAs, backup, integrity checks, and close behavior.</p><h2 id="canonical-sqlite-schema" tabindex="-1">Canonical SQLite schema <a class="header-anchor" href="#canonical-sqlite-schema" aria-label="Permalink to &quot;Canonical SQLite schema&quot;">​</a></h2><p>The common application schema can express the existing column types, nullability, primary keys, named check constraints, and expiry index with <code>sqliteTable</code>, <code>text</code>, <code>integer</code>, <code>check</code>, and <code>index</code>. The table API accepts columns plus extra constraints/indexes; the SQLite snapshot serializer records columns, indexes, foreign keys, primary keys, unique constraints, and checks. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/sqlite-core/table.ts#L59-L160" target="_blank" rel="noreferrer">Tagged table API</a> and <a href="https://github.com/drizzle-team/drizzle-orm/blob/drizzle-kit%400.31.10/drizzle-kit/src/serializer/sqliteSchema.ts#L57-L80" target="_blank" rel="noreferrer">tagged SQLite snapshot shape</a></p><p>Schema implications:</p><ul><li>Keep <code>lease_expires_at</code>, <code>expires_at</code>, and <code>attempts</code> as ordinary numeric <code>integer()</code> columns. Drizzle&#39;s timestamp modes map numbers to <code>Date</code>; that would change the existing port&#39;s seconds-as-number contract. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/sqlite-core/columns/integer.ts#L66-L155" target="_blank" rel="noreferrer">Tagged integer and timestamp mapping</a></li><li><code>text({ enum: [...] })</code> narrows TypeScript insert/select types but does not validate runtime values or emit a database enum check. Keep an explicit named <code>check(...)</code> for <code>outcome</code>, and keep the non-negative attempts check. <a href="https://orm.drizzle.team/docs/sqlite/column-types#text" target="_blank" rel="noreferrer">Official Drizzle SQLite column documentation</a> and <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/sqlite-core/checks.ts#L1-L35" target="_blank" rel="noreferrer">tagged check builder</a></li><li>Keep adapter-owned migration bookkeeping out of the shared application schema. D1 owns <code>d1_migrations</code>; Bun owns <code>gateway_migrations</code> plus <code>minimum_reader</code>. They are intentionally different compatibility mechanisms, not one shared table.</li></ul><p>Neither the 0.45.2 <code>sqliteTable</code> API nor the 0.31.10 SQLite snapshot model has a <code>WITHOUT ROWID</code> table attribute. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/sqlite-core/table.ts#L59-L160" target="_blank" rel="noreferrer">Tagged table API</a> and <a href="https://github.com/drizzle-team/drizzle-orm/blob/drizzle-kit%400.31.10/drizzle-kit/src/serializer/sqliteSchema.ts#L40-L65" target="_blank" rel="noreferrer">tagged snapshot table model</a> Therefore:</p><ul><li>Preserve <code>apps/push-gateway/migrations/0001_initial.sql</code> rather than replacing it with freshly generated create-table SQL.</li><li>Manually review/augment any future generated create-table SQL that requires <code>WITHOUT ROWID</code>.</li><li>Keep a focused migration/source guard for <code>WITHOUT ROWID</code>, because Drizzle snapshot drift detection cannot detect that physical option.</li></ul><h2 id="query-builder-behavior-needed-by-the-adapters" tabindex="-1">Query-builder behavior needed by the adapters <a class="header-anchor" href="#query-builder-behavior-needed-by-the-adapters" aria-label="Permalink to &quot;Query-builder behavior needed by the adapters&quot;">​</a></h2><h3 id="conditional-upsert-and-claim-reservation-results" tabindex="-1">Conditional upsert and claim/reservation results <a class="header-anchor" href="#conditional-upsert-and-claim-reservation-results" aria-label="Permalink to &quot;Conditional upsert and claim/reservation results&quot;">​</a></h3><p>SQLite insert builders support <code>.onConflictDoUpdate({ target, set, targetWhere, setWhere })</code>. The old single <code>where</code> option is deprecated; <code>setWhere</code> is the update-side predicate and is the direct mapping for both current conditional upserts. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/sqlite-core/query-builders/insert.ts#L156-L164" target="_blank" rel="noreferrer">Tagged SQLite insert conflict API</a> and <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/sqlite-core/query-builders/insert.ts#L319-L365" target="_blank" rel="noreferrer">SQL construction</a></p><p>The tagged source itself still carries a TODO to add coverage for <code>targetWhere</code> and <code>setWhere</code>, so the repository&#39;s adapter parity tests should directly prove both the generated predicate and the no-update result. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/sqlite-core/query-builders/insert.ts#L156-L164" target="_blank" rel="noreferrer">Tagged conflict-option source</a></p><p>Values in <code>.values()</code> and <code>.set()</code> are parameterized; a small <code>sql</code> fragment is still needed where the SQL <code>excluded</code> pseudo-table is semantically important, such as <code>attempts + excluded.attempts</code>. The official upsert examples use <code>sql\\</code>excluded.name\`\` for this case. <a href="https://orm.drizzle.team/docs/insert#upserts-and-conflicts" target="_blank" rel="noreferrer">Drizzle insert/upsert documentation</a></p><p>SQLite supports <code>RETURNING</code> for insert, update, and delete, and reports inserted or updated rows from an upsert. <a href="https://www.sqlite.org/lang_returning.html" target="_blank" rel="noreferrer">SQLite <code>RETURNING</code> contract</a> Drizzle&#39;s SQLite insert builder supports full or partial <code>.returning(...)</code>, followed by <code>all()</code>, <code>get()</code>, or normal awaited execution. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/sqlite-core/query-builders/insert.ts#L253-L282" target="_blank" rel="noreferrer">Tagged SQLite returning API</a> and <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/sqlite-core/query-builders/insert.ts#L378-L415" target="_blank" rel="noreferrer">execution methods</a></p><p>Use a returned-row array for claim/reservation decisions:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">acquired</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">insert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(deliveryRecords)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">values</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* ... */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">onConflictDoUpdate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    target: deliveryRecords.fingerprint,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    set: </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* ... */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    setWhere: </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* lease-expiry predicate */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  })</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">returning</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ fingerprint: deliveryRecords.fingerprint });</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> didAcquire</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> acquired </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> undefined</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>This avoids two edge cases in 0.45.2:</p><ul><li>Both D1 and Bun return <code>undefined</code> from prepared <code>get()</code> when no row is returned. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/d1/session.ts#L238-L258" target="_blank" rel="noreferrer">D1 implementation</a> and <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/bun-sqlite/session.ts#L143-L162" target="_blank" rel="noreferrer">Bun implementation</a></li><li>The SQLite DML prepared-query type declares <code>get</code> as the returned row type, without <code>undefined</code>, even though the runtime can return <code>undefined</code> for a conditional upsert that modifies no row. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/sqlite-core/query-builders/insert.ts#L176-L187" target="_blank" rel="noreferrer">Tagged insert prepared-query type</a></li></ul><p><code>$returningId()</code> is not a SQLite insert API. In 0.45.2 it is implemented on the MySQL and SingleStore builders, while the SQLite builder exposes native SQLite <code>returning()</code>. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/mysql-core/query-builders/insert.ts#L281-L294" target="_blank" rel="noreferrer">Tagged MySQL <code>$returningId()</code> implementation</a>, <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/singlestore-core/query-builders/insert.ts#L254-L267" target="_blank" rel="noreferrer">tagged SingleStore implementation</a>, and <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/sqlite-core/query-builders/insert.ts#L253-L365" target="_blank" rel="noreferrer">tagged SQLite insert API</a></p><h3 id="select-update-and-delete" tabindex="-1">Select, update, and delete <a class="header-anchor" href="#select-update-and-delete" aria-label="Permalink to &quot;Select, update, and delete&quot;">​</a></h3><ul><li><code>db.select({...}).from(table).where(...)</code> infers row nullability and selected fields. A prepared select&#39;s <code>get()</code> type correctly includes <code>undefined</code>; add <code>limit(1)</code> when only one row is wanted. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/sqlite-core/query-builders/select.ts#L584-L626" target="_blank" rel="noreferrer">Tagged select filtering</a> and <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/sqlite-core/query-builders/select.types.ts#L257-L267" target="_blank" rel="noreferrer">prepared select result types</a></li><li><code>db.update(table).set(...).where(...)</code> supports partial/full <code>returning()</code>. Omitting <code>where()</code> updates every row, so every adapter update should retain an explicit predicate. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/sqlite-core/query-builders/update.ts#L311-L410" target="_blank" rel="noreferrer">Tagged update API</a></li><li><code>db.delete(table).where(...)</code> supports partial/full <code>returning()</code>. Omitting <code>where()</code> deletes every row, so cleanup and release operations must keep explicit predicates. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/sqlite-core/query-builders/delete.ts#L159-L253" target="_blank" rel="noreferrer">Tagged delete API</a></li></ul><p>For D1 cleanup/readiness groups, pass the unexecuted builders directly to <code>db.batch([...])</code>. The returned tuple contains mapped row/run results. Retain native <code>$client.batch(...)</code> only where the native <code>D1Result</code> shape or deliberately raw statements are part of the behavior being proved.</p><h2 id="drizzle-kit-configuration-and-artifact-lineage" tabindex="-1">Drizzle Kit configuration and artifact lineage <a class="header-anchor" href="#drizzle-kit-configuration-and-artifact-lineage" aria-label="Permalink to &quot;Drizzle Kit configuration and artifact lineage&quot;">​</a></h2><h3 id="what-the-two-configurations-should-mean" tabindex="-1">What the two configurations should mean <a class="header-anchor" href="#what-the-two-configurations-should-mean" aria-label="Permalink to &quot;What the two configurations should mean&quot;">​</a></h3><p>Drizzle Kit supports multiple configuration files selected with <code>--config</code>. <a href="https://orm.drizzle.team/docs/drizzle-kit-generate#multiple-configuration-files-in-one-project" target="_blank" rel="noreferrer">Official multiple-config documentation</a> For <code>generate</code>, 0.31.10 consumes <code>dialect</code>, <code>schema</code>, <code>out</code>, <code>breakpoints</code>, migration <code>prefix</code>, <code>casing</code>, and a small driver-derived bundling flag; it does not require or consume database credentials. <a href="https://github.com/drizzle-team/drizzle-orm/blob/drizzle-kit%400.31.10/drizzle-kit/src/cli/commands/utils.ts#L150-L216" target="_blank" rel="noreferrer">Tagged <code>GenerateConfig</code> and parser</a></p><p>Accordingly, the D1 and Bun files should be offline generation profiles with:</p><ul><li><code>dialect: &#39;sqlite&#39;</code> in both;</li><li>the same canonical schema path;</li><li>the same canonical migration <code>out</code> directory;</li><li>identical <code>casing</code>, <code>breakpoints</code>, and <code>migrations.prefix</code> values;</li><li>no production credentials.</li></ul><p><code>driver: &#39;d1-http&#39;</code> is needed for Drizzle Kit commands that connect to D1, not for SQLite SQL generation. Since this repository must not use Kit to apply schema, omitting connection credentials keeps the configurations generation-only. Drizzle Kit <code>push</code> explicitly introspects a live database and immediately applies its generated differences, which conflicts with reviewed SQL and the retained runners. <a href="https://orm.drizzle.team/docs/drizzle-kit-push" target="_blank" rel="noreferrer">Official <code>push</code> behavior</a></p><p>Both configurations must share one <code>out</code> directory to represent one migration/snapshot lineage. Separate output directories would create two independent histories with different metadata. Generation should be sequential: 0.31.10 reads the journal, computes the next index, and writes it later without a locking protocol, so two concurrent generators sharing an output directory can race. This is an inference from the tagged <a href="https://github.com/drizzle-team/drizzle-orm/blob/drizzle-kit%400.31.10/drizzle-kit/src/utils.ts#L96-L112" target="_blank" rel="noreferrer">journal read path</a> and <a href="https://github.com/drizzle-team/drizzle-orm/blob/drizzle-kit%400.31.10/drizzle-kit/src/cli/commands/migrate.ts#L1394-L1439" target="_blank" rel="noreferrer">artifact write path</a>.</p><h3 id="existing-0001-initial-sql-needs-an-adopted-baseline-snapshot" tabindex="-1">Existing <code>0001_initial.sql</code> needs an adopted baseline snapshot <a class="header-anchor" href="#existing-0001-initial-sql-needs-an-adopted-baseline-snapshot" aria-label="Permalink to &quot;Existing \`0001_initial.sql\` needs an adopted baseline snapshot&quot;">​</a></h3><p><code>generate</code> reads the latest committed snapshot and compares it with the current schema. If no metadata directory exists, 0.31.10 creates an empty journal and treats the previous SQLite schema as empty. <a href="https://github.com/drizzle-team/drizzle-orm/blob/drizzle-kit%400.31.10/drizzle-kit/src/utils.ts#L96-L112" target="_blank" rel="noreferrer">Tagged output-folder preparation</a>, <a href="https://github.com/drizzle-team/drizzle-orm/blob/drizzle-kit%400.31.10/drizzle-kit/src/serializer/sqliteSchema.ts#L332-L344" target="_blank" rel="noreferrer">empty SQLite snapshot</a>, and <a href="https://github.com/drizzle-team/drizzle-orm/blob/drizzle-kit%400.31.10/drizzle-kit/src/cli/commands/migrate.ts#L802-L859" target="_blank" rel="noreferrer">generation flow</a></p><p>Therefore merely adding a schema/config beside the existing raw migration would generate a second create-table migration. <code>--custom</code> is not a baseline-adoption switch: the custom path writes a new snapshot whose schema body is copied from the previous snapshot, not the current declared schema. <a href="https://github.com/drizzle-team/drizzle-orm/blob/drizzle-kit%400.31.10/drizzle-kit/src/migrationPreparator.ts#L137-L168" target="_blank" rel="noreferrer">Tagged custom snapshot construction</a> and <a href="https://github.com/drizzle-team/drizzle-orm/blob/drizzle-kit%400.31.10/drizzle-kit/src/cli/commands/migrate.ts#L817-L832" target="_blank" rel="noreferrer">custom generation branch</a></p><p>Bootstrap implication:</p><ol><li>Generate the initial logical SQLite snapshot in an isolated temporary output using the exact pinned versions.</li><li>Keep the repository&#39;s <code>0001_initial.sql</code> content and identifier unchanged.</li><li>Adopt the generated snapshot and journal as the baseline lineage, reconciling their tag/index with <code>0001_initial</code> in a deterministic script or reviewed one-time step.</li><li>Prove the result with <code>drizzle-kit check</code> and a clean no-op <code>generate</code> from each configuration before committing it.</li></ol><p>This one-time adoption should be covered by a test/guard because Drizzle Kit 0.31.10 has no first-class <code>generate --baseline-existing-sql</code> option in its tagged generate CLI options. <a href="https://github.com/drizzle-team/drizzle-orm/blob/drizzle-kit%400.31.10/drizzle-kit/src/cli/schema.ts#L50-L80" target="_blank" rel="noreferrer">Tagged generate CLI options</a></p><h3 id="determinism-and-drift-detection" tabindex="-1">Determinism and drift detection <a class="header-anchor" href="#determinism-and-drift-detection" aria-label="Permalink to &quot;Determinism and drift detection&quot;">​</a></h3><p>Clean-room generation is not byte-deterministic in 0.31.10:</p><ul><li>every new SQLite snapshot gets <code>crypto.randomUUID()</code>; <a href="https://github.com/drizzle-team/drizzle-orm/blob/drizzle-kit%400.31.10/drizzle-kit/src/migrationPreparator.ts#L137-L168" target="_blank" rel="noreferrer">tagged snapshot preparation</a></li><li>an omitted migration name gets a random adjective/hero suffix, while timestamp/unix prefix modes use the wall clock; <a href="https://github.com/drizzle-team/drizzle-orm/blob/drizzle-kit%400.31.10/drizzle-kit/src/utils/words.ts#L3-L23" target="_blank" rel="noreferrer">tagged migration naming</a></li><li>each journal entry writes <code>when: +new Date()</code>. <a href="https://github.com/drizzle-team/drizzle-orm/blob/drizzle-kit%400.31.10/drizzle-kit/src/cli/commands/migrate.ts#L1429-L1439" target="_blank" rel="noreferrer">Tagged artifact writer</a></li></ul><p>Use <code>migrations.prefix: &#39;index&#39;</code> and require the repository wrapper to assign an explicit name for real migrations, but recognize that UUID and journal time still vary. Drizzle Kit 0.31.10 rejects combining <code>--config</code> with generation flags such as <code>--name</code> or <code>--out</code>, so the wrapper must invoke each named config on its own, then safely normalize the generated SQL filename and matching journal tag. In this tool version, the useful deterministic invariant is: <strong>the committed snapshot lineage plus an unchanged schema must make generation a no-op</strong>. When the SQL diff is empty, the writer returns before it persists the newly-created in-memory UUID or time. <a href="https://github.com/drizzle-team/drizzle-orm/blob/drizzle-kit%400.31.10/drizzle-kit/src/cli/commands/migrate.ts#L1385-L1391" target="_blank" rel="noreferrer">Tagged no-change branch</a></p><p>A CI drift target should therefore:</p><ol><li>Run <code>drizzle-kit check</code> on the canonical output to reject malformed, outdated, or colliding snapshot history. The check validates history shape; it does not compare the TypeScript schema with the latest snapshot. <a href="https://github.com/drizzle-team/drizzle-orm/blob/drizzle-kit%400.31.10/drizzle-kit/src/cli/commands/check.ts#L4-L50" target="_blank" rel="noreferrer">Tagged check implementation</a></li><li>Run <code>generate --config=&lt;d1&gt;</code> and the Bun equivalent sequentially against temporary copies of the committed lineage, using the shared config&#39;s check-only output override rather than mixing config and CLI flags.</li><li>Require the no-schema-change outcome and verify that no tracked or untracked artifact changed.</li><li>Verify that the two configs have identical generation-relevant fields, so one runtime profile cannot silently fork the SQL.</li></ol><p>Do not trust the <code>generate</code> process exit code alone for this check. The SQLite generation function catches and logs exceptions without rethrowing them at that point, so the wrapper should fail on generator errors/stderr as well as artifact drift. <a href="https://github.com/drizzle-team/drizzle-orm/blob/drizzle-kit%400.31.10/drizzle-kit/src/cli/commands/migrate.ts#L802-L862" target="_blank" rel="noreferrer">Tagged SQLite generator error path</a></p><p>If acceptance requires byte-for-byte clean-room reproduction rather than stable no-op regeneration, a repository wrapper must additionally normalize or deterministically replace snapshot <code>id</code>, <code>prevId</code>, journal <code>when</code>, and the migration name before comparison. Drizzle Kit 0.31.10 does not provide such normalization.</p><h2 id="migration-runners-and-raw-boundaries" tabindex="-1">Migration runners and raw boundaries <a class="header-anchor" href="#migration-runners-and-raw-boundaries" aria-label="Permalink to &quot;Migration runners and raw boundaries&quot;">​</a></h2><p>Do not use the runtime Drizzle migrators:</p><ul><li>The D1 migrator reads Drizzle Kit <code>_journal.json</code>, creates <code>__drizzle_migrations</code> by default with <code>hash</code> and <code>created_at</code>, and submits statements through its own batch. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/d1/migrator.ts#L6-L48" target="_blank" rel="noreferrer">Tagged D1 migrator</a></li><li>The Bun migrator delegates to the synchronous SQLite dialect, which uses the same hash/time bookkeeping and a plain <code>BEGIN</code>, not this repository&#39;s <code>BEGIN IMMEDIATE</code> plus migration name/minimum-reader contract. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/bun-sqlite/migrator.ts#L5-L10" target="_blank" rel="noreferrer">Tagged Bun migrator</a> and <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/sqlite-core/dialect.ts#L936-L995" target="_blank" rel="noreferrer">tagged synchronous SQLite migrator</a></li><li>Drizzle&#39;s migration reader recognizes journal time, SQL hash, and statement breakpoints; it has no <code>minimum_reader</code> concept. <a href="https://github.com/drizzle-team/drizzle-orm/blob/0.45.2/drizzle-orm/src/migrator.ts#L9-L59" target="_blank" rel="noreferrer">Tagged migration metadata reader</a></li></ul><p>Wrangler should continue applying D1 migrations. Cloudflare records versioned SQL filenames sequentially in <code>d1_migrations</code>, and <code>wrangler d1 migrations apply</code> rolls back a failing migration while retaining earlier successful migrations. <a href="https://developers.cloudflare.com/d1/reference/migrations/" target="_blank" rel="noreferrer">D1 migrations reference</a> and <a href="https://developers.cloudflare.com/workers/wrangler/commands/d1/#d1-migrations-apply" target="_blank" rel="noreferrer">Wrangler apply contract</a></p><p>The custom Bun runner should continue owning:</p><ul><li>ordered filename identifiers;</li><li><code>minimum-reader</code> metadata and immediate-predecessor compatibility;</li><li><code>BEGIN IMMEDIATE</code> application;</li><li>startup validation and rollback behavior.</li></ul><p>Generated SQL remains an input to review, not the complete migration contract. Preserve/add the <code>minimum-reader</code> header as required, verify expand-first compatibility, and manually retain <code>WITHOUT ROWID</code> where applicable. Drizzle Kit&#39;s default statement-breakpoint marker is controlled by <code>breakpoints</code>; use the same explicit setting in both configs. <a href="https://github.com/drizzle-team/drizzle-orm/blob/drizzle-kit%400.31.10/drizzle-kit/src/cli/commands/utils.ts#L169-L216" target="_blank" rel="noreferrer">Tagged breakpoint default and generation config</a> and <a href="https://github.com/drizzle-team/drizzle-orm/blob/drizzle-kit%400.31.10/drizzle-kit/src/cli/commands/migrate.ts#L1354-L1439" target="_blank" rel="noreferrer">tagged SQL writer</a></p><p>Keep these operations narrow and raw/native, matching issue #21:</p><ul><li>connection PRAGMAs;</li><li>Bun <code>BEGIN IMMEDIATE</code>, commit, rollback, and savepoint-sensitive startup/migration work;</li><li>D1 batch boundaries where atomic grouping is the contract;</li><li>migration and compatibility inspection, including adapter-owned metadata tables;</li><li><code>pragma_table_info</code>, <code>sqlite_master</code>, and schema/readiness inspection;</li><li><code>VACUUM INTO</code>, integrity checks, and backup lifecycle;</li><li>physical <code>WITHOUT ROWID</code> DDL.</li></ul><h2 id="implementation-ready-implications" tabindex="-1">Implementation-ready implications <a class="header-anchor" href="#implementation-ready-implications" aria-label="Permalink to &quot;Implementation-ready implications&quot;">​</a></h2><ul><li>Share table definitions and query helpers, not a database instance or transaction abstraction.</li><li>Wrap the existing native clients so Bun strict/configuration/backup behavior and the D1 binding survive unchanged.</li><li>Convert claim and budget reservation to <code>onConflictDoUpdate(...setWhere...).returning(...)</code>, and decide success from the returned array&#39;s first row.</li><li>Do not use <code>$returningId()</code> and do not retain <code>!== null</code> checks at Drizzle <code>get()</code> boundaries.</li><li>Use typed <code>select</code>, <code>update</code>, and <code>delete</code> for ordinary single statements; retain explicit predicates.</li><li>Use Drizzle <code>db.batch</code> only when its mapped results are desired; use D1 <code>$client.batch</code> when native result metadata/raw items are required.</li><li>Keep <code>0001_initial.sql</code>, Wrangler migration execution, the Bun compatibility runner, and every listed raw boundary.</li><li>Point both offline Kit configs at one schema and one output lineage, and serialize generation.</li><li>Adopt one reviewed baseline snapshot for the existing migration; then gate snapshot validity plus no-op regeneration from both configs.</li><li>Treat <code>WITHOUT ROWID</code> and <code>minimum-reader</code> as repository-level guards outside Drizzle&#39;s schema model.</li><li>Run adapter parity/concurrency/rollback tests and the repository&#39;s required Nx checks after implementation; generation success alone cannot prove the runtime contracts.</li></ul>`,77)])])}const u=t(o,[["render",n]]);export{m as __pageData,u as default};
